def balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set(pairs.values())
    stack = []
    in_string = False
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if in_string:
            if c == '\\':
                i += 2
                continue
            if c == '"':
                in_string = False
        else:
            if c == '"':
                in_string = True
            elif c in openers:
                stack.append(c)
            elif c in pairs:
                if not stack or stack[-1] != pairs[c]:
                    return False
                stack.pop()
        i += 1
    if in_string:
        return False
    return not stack
